const std = @import("std");
const subject = @import("subject");
pub export fn agent_observe(index: u32) u64 {
    var storage: [256]u8 = undefined;
    var backing = std.heap.FixedBufferAllocator.init(&storage);
    var budget: subject.Budget = .{ .parent = backing.allocator(), .limit = 64 };
    const allocator = budget.allocator();
    const first = allocator.alloc(u8, 32) catch return 999;
    var rejected: u64 = 0;
    if (allocator.alloc(u8, 40)) |unexpected| { allocator.free(unexpected); } else |_| { rejected = 1; }
    const live = budget.live;
    const required = budget.required;
    const failed: u64 = @intFromBool(budget.failed);
    allocator.free(first);
    const whole = allocator.alloc(u8, 64) catch return 999;
    const peak = budget.peak;
    allocator.free(whole);
    budget.resetObservation();
    return switch (index) { 0 => rejected, 1 => live, 2 => required, 3 => failed, 4 => peak, 5 => budget.live, 6 => budget.peak, 7 => budget.required, 8 => @intFromBool(budget.failed), else => 999 };
}
